refentry.refsect1:
  &reftitle.description;

&style.procedural;

   intfalsenullgrapheme_strlen
   stringstring



   Lit la taille d'une chaîne en nombre de graphèmes (et non pas en
   octets ou caractères).

&reftitle.parameters;




   string



     La chaîne à mesurer. Elle doit être une chaîne UTF-8 valide.

  &reftitle.examples;

   Exemple avec grapheme_strlen


<?php

$char_a_ring_nfd = "a\xCC\x8A";  // 'LATIN SMALL LETTER A WITH RING ABOVE' (U+00E5) forme normalisée "D"
$char_o_diaeresis_nfd = "o\xCC\x88"; // 'LATIN SMALL LETTER O WITH DIAERESIS' (U+00F6) forme normalisée "D"

print grapheme_strlen( 'abc' . $char_a_ring_nfd . $char_o_diaeresis_nfd . $char_a_ring_nfd);

?>



  &example.outputs;


6



   Gestion d'une entrée UTF-8 invalide

    grapheme_strlen retourne &null; ou &false; en cas d'échec, y compris
    lorsque l'entrée n'est pas de l'UTF-8 valide.
    Utiliser intl_get_error_code et intl_error_name
    pour récupérer les détails de l'erreur ICU.



<?php

$string = "\xFF"; // séquence d'octets UTF-8 invalide
$length = grapheme_strlen($string);

if (!is_int($length)) {
    $code = intl_get_error_code();
    printf("grapheme_strlen() a échoué : %s (%d)\n", intl_error_name($code), $code);
} else {
    echo $length, PHP_EOL;
}

?>


   &example.outputs;


grapheme_strlen() a échoué : U_INVALID_CHAR_FOUND (10)

